int freeAllNodData() {
	int i;

	for (i = 0; i < model.nNoder; i++) {
		free(model.Noder[i].UtNod);
		model.Noder[i].UtNod = NULL;
		free(model.Noder[i].UtNodCost);
		free(model.Noder[i].outArcNr);
	}
	return 0;
}

int freeMemory() {
	int i;

	for (i = 0; i < model.nNoder; i++) {
		free(model.Noder[i].UtNod);
		free(model.Noder[i].UtNodCost);
		free(model.Noder[i].outArcNr);
	}
	free(model.Noder);

	exit(0);
	return 0;
}

