std::string splitFilename(std::string namn, int alt) {
	std::string resultat;
	size_t found;
	found = namn.find_last_of("/\\");
	if (alt == 0)
		resultat = namn.substr(0, found);
	else
		resultat = namn.substr(found + 1, namn.size());
	return resultat;
}

