void getBastSpeedPos(int nSettings, double target, int* indexUnder, int* indexOver, double* kvot) {
	int i, posUnder = -1, posOver = -1;
	double valUnder, valOver, minValUnder = 9999, minValOver = 9999, diff;

	for (i = 0; i < nSettings; i++) {
		if (target > model.functions.rpmSetting_gerCalmWaterSpeedBase[i]) {
			valUnder = target - model.functions.rpmSetting_gerCalmWaterSpeedBase[i];
			if (minValUnder > valUnder) {
				minValUnder = valUnder;
				posUnder = i;
			}
		}
		else {
			valOver = model.functions.rpmSetting_gerCalmWaterSpeedBase[i] - target;
			if (minValOver > valOver) {
				minValOver = valOver;
				posOver = i;
			}
		}
	}
	if (posUnder == -1) {
		*indexUnder = posOver;
		*indexOver = -1;
		*kvot = -1;
		if (minValOver > 0.001)
			errlog("ERROR! A speed of %.3lf knots is given but the lowest speed given for this digital ship is %.3lf which I will use\n",
				target / 1.852, (target + minValOver) / 1.852);
	}
	else if (posOver == -1) {
		*indexUnder = posUnder;
		*indexOver = -1;
		*kvot = -1;
		if (minValUnder > 0.001)
			errlog("ERROR! A speed of %.3lf knots is given but the highest speed given for this digital ship is %.3lf which I will use\n",
				target / 1.852, (target - minValUnder) / 1.852);
	}
	else {
		*indexUnder = posUnder;
		*indexOver = posOver;
		diff = model.functions.rpmSetting_gerCalmWaterSpeedBase[posOver] - model.functions.rpmSetting_gerCalmWaterSpeedBase[posUnder];
		if (diff < 0.0001) {
			*indexOver = -1;
			*kvot = -1;
		}
		else {
			*kvot = (target - model.functions.rpmSetting_gerCalmWaterSpeedBase[posUnder]) / diff;
		}
	}
	//printf("BastSpeedPos target %.2lf indexUnder/Over %d %d kvot %.3lf nSettings %d\n", target/1.852,
	//	*indexUnder, *indexOver, *kvot, nSettings);
}

void getBastConsumptionPos(int nSettings, double target, int* indexUnder, int* indexOver, double* kvot) {
	int i, posUnder = -1, posOver = -1;
	double valUnder, valOver, minValUnder = 9999, minValOver = 9999, fuel, diff;

	for (i = 0; i < nSettings; i++) {
		fuel = model.functions.rpmSetting_gerFuelConsumption_mainBase[i]; // only main engine +model.functions.rpmSetting_gerFuelConsumption_auxBase[i];
		if (target > fuel) {
			valUnder = target - fuel;
			if (minValUnder > valUnder) {
				minValUnder = valUnder;
				posUnder = i;
			}
		}
		else {
			valOver = fuel - target;
			if (minValOver > valOver) {
				minValOver = valOver;
				posOver = i;
			}
		}
	}
	if (posUnder == -1) {
		*indexUnder = posOver;
		*indexOver = -1;
		*kvot = -1;
		if(minValOver > 0.001)
			errlog("ERROR! A consumption of %.3lf mpd is given but the lowest consumption given for this digital ship is %.3lf (main) which I will use\n",
				target * 24.0, (target + minValOver) * 24.0);
	}
	else if (posOver == -1) {
		*indexUnder = posUnder;
		*indexOver = -1;
		*kvot = -1;
		if (minValUnder > 0.001)
			errlog("ERROR! A consumption of %.3lf mpd is given but the higest consumption given for this digital ship is %.3lf (main) which I will use\n",
				target * 24.0, (target - minValUnder) * 24.0);
	}
	else {
		*indexUnder = posUnder;
		*indexOver = posOver;
		diff = model.functions.rpmSetting_gerFuelConsumption_mainBase[posOver] -
			(model.functions.rpmSetting_gerFuelConsumption_mainBase[posUnder]);
		if (diff < 0.0001) {
			*indexOver = -1;
			*kvot = -1;
		}
		else {
			*kvot = (target - (model.functions.rpmSetting_gerFuelConsumption_mainBase[posUnder])) / diff;
		}
	}
	//printf("BastConsumptionPos target %.2lf indexUnder/Over %d %d kvot %.3lf\n", target,
	//	*indexUnder, *indexOver, *kvot);
}

int set_speedSettingsFromBase(strSpeed* speedSetting, int i, int iUse, int iOver, double kvot) {
	if (iOver == -1) {
		if (speedSetting != NULL) {
			speedSetting->rpm[i] = model.functions.rpmBase[iUse];
			speedSetting->rpmSetting_gerCalmWaterSpeed[i] = model.functions.rpmSetting_gerCalmWaterSpeedBase[iUse];
			speedSetting->rpmSetting_gerFuelConsumption_main[i] = model.functions.rpmSetting_gerFuelConsumption_mainBase[iUse];
			speedSetting->rpmSetting_gerFuelConsumption_aux[i] = model.functions.rpmSetting_gerFuelConsumption_auxBase[iUse];
			speedSetting->settingGerBaseSetting[i] = iUse;
		}
		else {
			model.functions.rpmSetting_gerCalmWaterSpeedDelay[i] = model.functions.rpmSetting_gerCalmWaterSpeedBase[iUse];
			model.functions.rpmSetting_gerFuelConsumption_mainDelay[i] = model.functions.rpmSetting_gerFuelConsumption_mainBase[iUse];
			model.functions.rpmSetting_gerFuelConsumption_auxDelay[i] = model.functions.rpmSetting_gerFuelConsumption_auxBase[iUse];
		}
	}
	else {
		if (speedSetting != NULL) {
			speedSetting->rpm[i] = model.functions.rpmBase[iUse] * (1 - kvot) + model.functions.rpmBase[iOver] * kvot;
			speedSetting->rpmSetting_gerCalmWaterSpeed[i] = model.functions.rpmSetting_gerCalmWaterSpeedBase[iUse] * (1 - kvot) + model.functions.rpmSetting_gerCalmWaterSpeedBase[iOver] * kvot;
			speedSetting->rpmSetting_gerFuelConsumption_main[i] = model.functions.rpmSetting_gerFuelConsumption_mainBase[iUse] * (1 - kvot) + model.functions.rpmSetting_gerFuelConsumption_mainBase[iOver] * kvot;
			speedSetting->rpmSetting_gerFuelConsumption_aux[i] = model.functions.rpmSetting_gerFuelConsumption_auxBase[iUse] * (1 - kvot) + model.functions.rpmSetting_gerFuelConsumption_auxBase[iOver] * kvot;
			if (kvot <= 0.5)
				speedSetting->settingGerBaseSetting[i] = iUse;
			else
				speedSetting->settingGerBaseSetting[i] = iOver;
		}
		else {
			model.functions.rpmSetting_gerCalmWaterSpeedDelay[i] = model.functions.rpmSetting_gerCalmWaterSpeedBase[iUse] * (1 - kvot) + model.functions.rpmSetting_gerCalmWaterSpeedBase[iOver] * kvot;
			model.functions.rpmSetting_gerFuelConsumption_mainDelay[i] = model.functions.rpmSetting_gerFuelConsumption_mainBase[iUse] * (1 - kvot) + model.functions.rpmSetting_gerFuelConsumption_mainBase[iOver] * kvot;
			model.functions.rpmSetting_gerFuelConsumption_auxDelay[i] = model.functions.rpmSetting_gerFuelConsumption_auxBase[iUse] * (1 - kvot) + model.functions.rpmSetting_gerFuelConsumption_auxBase[iOver] * kvot;
		}
	}
	return 0;
}

int getBaseSpeedSetting(int speedSetting, int lev1, int lev2) {
	int speedNr;
	if (lev1 >= 0)
		speedNr = model.functions.speedLevel[lev1].settingGerBaseSetting[speedSetting];
	else {
		if (lev2 >= 0)
			speedNr = model.functions.speedChannelOut[-lev1 - 1].settingGerBaseSetting[speedSetting];
		else
			speedNr = model.functions.speedChannel[-lev1 - 1].settingGerBaseSetting[speedSetting];
	}
	return speedNr;
}


int getClosestSetting_fromBase(int baseSetting, int fromLevel, int toLevel) {
	int i;

	strSpeed* speedSetting;

	if (fromLevel >= 0)
		speedSetting = &(model.functions.speedLevel[fromLevel]);
	else {
		if (toLevel >= 0)
			speedSetting = &(model.functions.speedChannelOut[-fromLevel - 1]);
		else
			speedSetting = &(model.functions.speedChannel[-fromLevel - 1]);
	}

	for (i = 0; i < speedSetting->nShip_speedSettings; i++) {
		if (baseSetting <= speedSetting->settingGerBaseSetting[i])
			break;
	}
	if (i >= speedSetting->nShip_speedSettings)
		return speedSetting->nShip_speedSettings - 1;
	if (i == 0)
		return i;
	if (baseSetting - speedSetting->settingGerBaseSetting[i - 1] <= speedSetting->settingGerBaseSetting[i] - baseSetting)
		return i - 1;
	else
		return i;
}

void setupUsableSpeedSettings() {
	int nAlloc, minPos = 0, maxPos = 0, midPos, add95, iUse, i, indexUnder, indexOver, i1;
	int nextTraff;
	double min_rpm, max_rpm, midVal, diff, min_diff, delta, target, kvot;

	model.functions.speedLevel = (strSpeed*)malloc2(model.network.nPhysicalLevels * sizeof(strSpeed));
	model.functions.speedChannel = (strSpeed*)malloc2(model.network.nChannels * sizeof(strSpeed));
	model.functions.speedChannelOut = (strSpeed*)malloc2(model.network.nChannels * sizeof(strSpeed));
	model.functions.rpmSetting_gerCalmWaterSpeedDelay = (double*)malloc(model.functions.nShip_speedSettingsBase * sizeof(double));
	model.functions.rpmSetting_gerFuelConsumption_mainDelay = (double*)malloc(model.functions.nShip_speedSettingsBase * sizeof(double));
	model.functions.rpmSetting_gerFuelConsumption_auxDelay = (double*)malloc(model.functions.nShip_speedSettingsBase * sizeof(double));

	int nShip_speedSettings;
	double maxSpeed = 0, minSpeed = 1e10;

	for (i = 0; i < model.functions.nShip_speedSettingsBase; i++) {
		if (minSpeed > model.functions.rpmSetting_gerCalmWaterSpeedBase[i]) {
			minSpeed = model.functions.rpmSetting_gerCalmWaterSpeedBase[i];
			minPos = i;
		}
		if (maxSpeed < model.functions.rpmSetting_gerCalmWaterSpeedBase[i]) {
			maxSpeed = model.functions.rpmSetting_gerCalmWaterSpeedBase[i];
			maxPos = i;
		}
	}

	if (model.params.commercialAllowedVariation < 0) {
		// not commercial
		nShip_speedSettings = model.params.nSpeedSettingDivideIter1 + 1;
		nAlloc = model.functions.nShip_speedSettingsBase; //  5;
	}
	else {
		// commercial version
		if (model.params.commercialAllowedVariation < 0.001) {
			model.params.commercialAllowedVariation = 0;
			nShip_speedSettings = 1;
			nAlloc = 1;
		}
		else {
			nShip_speedSettings = 5;
			nAlloc = 5;
		}
	}
	model.functions.nAllocShipSpeedsLevel = nAlloc;
	if (nShip_speedSettings > model.functions.nShip_speedSettingsBase)
		nShip_speedSettings = model.functions.nShip_speedSettingsBase;

	for (i = 0; i < model.network.nPhysicalLevels; i++) {
		model.functions.speedLevel[i].rpm = (double*)malloc2(nAlloc * sizeof(double));
		model.functions.speedLevel[i].rpmSetting_gerCalmWaterSpeed = (double*)malloc2(nAlloc * sizeof(double));
		model.functions.speedLevel[i].rpmSetting_gerFuelConsumption_main = (double*)malloc2(nAlloc * sizeof(double));
		model.functions.speedLevel[i].rpmSetting_gerFuelConsumption_aux = (double*)malloc2(nAlloc * sizeof(double));
		model.functions.speedLevel[i].settingGerBaseSetting = (int*)malloc2(nAlloc * sizeof(int));
		model.functions.speedLevel[i].nShip_speedSettings = nShip_speedSettings;
	}

	model.functions.speedSetting95MCR_use = model.functions.speedSetting95MCR_base;
	if (model.functions.speedSetting95MCR_use < nShip_speedSettings && model.params.commercialAllowedVariation >= 0)
		model.functions.speedSetting95MCR_use = nShip_speedSettings;

	nAlloc = model.functions.nShip_speedSettingsBase;
	if (nAlloc <= model.functions.speedSetting95MCR_use)
		nAlloc = model.functions.speedSetting95MCR_use + 1;
	for (i = 0; i < model.network.nChannels; i++) {
		model.functions.speedChannel[i].rpm = (double*)malloc2(nAlloc * sizeof(double));
		model.functions.speedChannel[i].rpmSetting_gerCalmWaterSpeed = (double*)malloc2(nAlloc * sizeof(double));
		model.functions.speedChannel[i].rpmSetting_gerFuelConsumption_main = (double*)malloc2(nAlloc * sizeof(double));
		model.functions.speedChannel[i].rpmSetting_gerFuelConsumption_aux = (double*)malloc2(nAlloc * sizeof(double));
		model.functions.speedChannel[i].settingGerBaseSetting = (int*)malloc2(nAlloc * sizeof(int));
		model.functions.speedChannel[i].nShip_speedSettings = nShip_speedSettings;

		model.functions.speedChannelOut[i].rpm = (double*)malloc2(nAlloc * sizeof(double));
		model.functions.speedChannelOut[i].rpmSetting_gerCalmWaterSpeed = (double*)malloc2(nAlloc * sizeof(double));
		model.functions.speedChannelOut[i].rpmSetting_gerFuelConsumption_main = (double*)malloc2(nAlloc * sizeof(double));
		model.functions.speedChannelOut[i].rpmSetting_gerFuelConsumption_aux = (double*)malloc2(nAlloc * sizeof(double));
		model.functions.speedChannelOut[i].settingGerBaseSetting = (int*)malloc2(nAlloc * sizeof(int));
		model.functions.speedChannelOut[i].nShip_speedSettings = nShip_speedSettings;
	}

	double consumption, speed;
	if (model.params.commercialAllowedVariation < 0) {
		errlog("Not commercial opt, using %d speed settings of %d",
			nShip_speedSettings, model.functions.nShip_speedSettingsBase);

		model.functions.nShip_speedSettingsDelay = model.functions.nShip_speedSettingsBase;
		i = 0;
		nextTraff = roundUp(model.functions.nShip_speedSettingsBase / (double)model.params.nSpeedSettingDivideIter1);
		if (nextTraff == maxPos)
			nextTraff--;
		for (iUse = 0; iUse < model.functions.nShip_speedSettingsBase; iUse++) {
			set_speedSettingsFromBase(NULL, iUse, iUse);
			if (iUse == minPos || iUse == maxPos || iUse == nextTraff) {
				if (iUse == nextTraff)
					nextTraff += roundUp(model.functions.nShip_speedSettingsBase / (double)model.params.nSpeedSettingDivideIter1);
				for (i1 = 0; i1 < model.network.nPhysicalLevels; i1++) {
					set_speedSettingsFromBase(&(model.functions.speedLevel[i1]), i, iUse);
					if (i1 == 0)
						errlog(" %d %.2lf", i, model.functions.speedLevel[i1].rpmSetting_gerCalmWaterSpeed[i] / model.params.knots_to_km);
				}
				for (i1 = 0; i1 < model.network.nChannels; i1++) {
					if (model.network.channel[i1].timeThroughChannel > 0) {
						if (i == 0) {
							consumption = model.network.channel[i1].totalConsumption / model.network.channel[i1].timeThroughChannel;
							speed = model.network.channel[i1].distance_km / model.network.channel[i1].timeThroughChannel;
							set_speedSettingsFromBase(&(model.functions.speedChannel[i1]), i, iUse);
							model.functions.speedChannel[i1].nShip_speedSettings = 1;
							model.functions.speedChannel[i1].rpmSetting_gerCalmWaterSpeed[i] = speed;
							model.functions.speedChannel[i1].rpmSetting_gerFuelConsumption_main[i] = consumption;

							set_speedSettingsFromBase(&(model.functions.speedChannelOut[i1]), i, iUse);
							model.functions.speedChannelOut[i1].nShip_speedSettings = 1;
							model.functions.speedChannelOut[i1].rpmSetting_gerCalmWaterSpeed[i] = speed;
							model.functions.speedChannelOut[i1].rpmSetting_gerFuelConsumption_main[i] = consumption;
						}
						else
							continue;
					}
					else {
						set_speedSettingsFromBase(&(model.functions.speedChannel[i1]), i, iUse);
						set_speedSettingsFromBase(&(model.functions.speedChannelOut[i1]), i, iUse);
						if (iUse == maxPos) {
							set_speedSettingsFromBase(&(model.functions.speedChannel[i1]), iUse, iUse);
							set_speedSettingsFromBase(&(model.functions.speedChannelOut[i1]), iUse, iUse);
						}
					}
				}
				i++;
			}
		}
		errlog(" knots\n");
		model.functions.speedSetting95MCR_base = maxPos;
	}
	else {
		// commercial version

		model.functions.nShip_speedSettingsDelay = nShip_speedSettings;
		for (i = 0; i < nShip_speedSettings; i++) {
			if (i == 0)
				delta = 1 - model.params.commercialAllowedVariation / 100.0;
			else if (i == 1)
				delta = 1 - model.params.commercialAllowedVariation / 100.0 / 2.0;
			else if (i == 2)
				delta = 1;
			else if (i == 3)
				delta = 1 + model.params.commercialAllowedVariation / 100.0 / 2.0;
			else
				delta = 1 + model.params.commercialAllowedVariation / 100.0;
			if (model.params.commercialSpeed > 0) {
				target = model.params.commercialSpeed * model.params.knots_to_km * delta;
				getBastSpeedPos(model.functions.nShip_speedSettingsBase, target, &indexUnder, &indexOver, &kvot);
			}
			else {
				target = model.params.commercialFuel * delta / 24.0;
				getBastConsumptionPos(model.functions.nShip_speedSettingsBase, target, &indexUnder, &indexOver, &kvot);
			}

			if (kvot < 0) {
				set_speedSettingsFromBase(NULL, i, indexUnder);
				for (i1 = 0; i1 < model.network.nPhysicalLevels; i1++) {
					set_speedSettingsFromBase(&(model.functions.speedLevel[i1]), i, indexUnder);
					set_speedSettingsFromBase(NULL, i, indexUnder);
				}
				for (i1 = 0; i1 < model.network.nChannels; i1++) {
					if (model.network.channel[i1].timeThroughChannel > 0) {
						if (i == 0) {
							consumption = model.network.channel[i1].totalConsumption / model.network.channel[i1].timeThroughChannel;
							speed = model.network.channel[i1].distance_km / model.network.channel[i1].timeThroughChannel;
							set_speedSettingsFromBase(&(model.functions.speedChannel[i1]), i, i);
							model.functions.speedChannel[i1].nShip_speedSettings = 1;
							model.functions.speedChannel[i1].rpmSetting_gerCalmWaterSpeed[i] = speed;
							model.functions.speedChannel[i1].rpmSetting_gerFuelConsumption_main[i] = consumption;

							set_speedSettingsFromBase(&(model.functions.speedChannelOut[i1]), i, i);
							model.functions.speedChannelOut[i1].nShip_speedSettings = 1;
							model.functions.speedChannelOut[i1].rpmSetting_gerCalmWaterSpeed[i] = speed;
							model.functions.speedChannelOut[i1].rpmSetting_gerFuelConsumption_main[i] = consumption;
						}
						else
							continue;
					}
					else {
						set_speedSettingsFromBase(&(model.functions.speedChannel[i1]), i, indexUnder);
						set_speedSettingsFromBase(&(model.functions.speedChannelOut[i1]), i, indexUnder);
					}
				}
			}
			else {
				set_speedSettingsFromBase(NULL, i, indexUnder, indexOver, kvot);
				for (i1 = 0; i1 < model.network.nPhysicalLevels; i1++) {
					set_speedSettingsFromBase(&(model.functions.speedLevel[i1]), i, indexUnder, indexOver, kvot);
				}
				for (i1 = 0; i1 < model.network.nChannels; i1++) {
					if (model.network.channel[i1].timeThroughChannel > 0) {
						if (i == 0) {
							consumption = model.network.channel[i1].totalConsumption / model.network.channel[i1].timeThroughChannel;
							speed = model.network.channel[i1].distance_km / model.network.channel[i1].timeThroughChannel;
							set_speedSettingsFromBase(&(model.functions.speedChannel[i1]), i, i);
							model.functions.speedChannel[i1].nShip_speedSettings = 1;
							model.functions.speedChannel[i1].rpmSetting_gerCalmWaterSpeed[i] = speed;
							model.functions.speedChannel[i1].rpmSetting_gerFuelConsumption_main[i] = consumption;

							set_speedSettingsFromBase(&(model.functions.speedChannelOut[i1]), i, i);
							model.functions.speedChannelOut[i1].nShip_speedSettings = 1;
							model.functions.speedChannelOut[i1].rpmSetting_gerCalmWaterSpeed[i] = speed;
							model.functions.speedChannelOut[i1].rpmSetting_gerFuelConsumption_main[i] = consumption;
						}
						else
							continue;
					}
					else {
						set_speedSettingsFromBase(&(model.functions.speedChannel[i1]), i, indexUnder, indexOver, kvot);
						set_speedSettingsFromBase(&(model.functions.speedChannelOut[i1]), i, indexUnder, indexOver, kvot);
					}
				}
			}
		}

		iUse = model.functions.speedSetting95MCR_use;
		for (i1 = 0; i1 < model.network.nChannels; i1++) {
			set_speedSettingsFromBase(&(model.functions.speedChannel[i1]), iUse, model.functions.speedSetting95MCR_base);
			set_speedSettingsFromBase(&(model.functions.speedChannelOut[i1]), iUse, model.functions.speedSetting95MCR_base);
		}

		errlog("OBS! commercial opt, using %d speed settings with allowedVariation %.2lf Speed %.2lf fuel %.2lf, with data interpolated from the speed/fuel table by Trung, calmwaterspeeds",
			model.functions.speedLevel[0].nShip_speedSettings, model.params.commercialAllowedVariation, model.params.commercialSpeed, model.params.commercialFuel);
		for (i = 0; i < model.functions.speedLevel[0].nShip_speedSettings; i++)
			errlog(" %d %.2lf", i, model.functions.speedLevel[0].rpmSetting_gerCalmWaterSpeed[i] / model.params.knots_to_km);

		errlog(" knots, fuel consumption main/aux ");
		for (i = 0; i < model.functions.speedLevel[0].nShip_speedSettings; i++)
			errlog(" %d %.2lf %.2lf", i, model.functions.speedLevel[0].rpmSetting_gerFuelConsumption_main[i] * 24.0,
				model.functions.speedLevel[0].rpmSetting_gerFuelConsumption_aux[i] * 24.0);
		errlog(" mpd\n");
	}

	double averSpeed = 0;
	minSpeed = 1e10;
	maxSpeed = 0;
	for (i = 0; i < model.functions.speedLevel[0].nShip_speedSettings; i++) {
		averSpeed += model.functions.speedLevel[0].rpmSetting_gerCalmWaterSpeed[i];
		if (minSpeed > model.functions.speedLevel[0].rpmSetting_gerCalmWaterSpeed[i])
			minSpeed = model.functions.speedLevel[0].rpmSetting_gerCalmWaterSpeed[i];
		if (maxSpeed < model.functions.speedLevel[0].rpmSetting_gerCalmWaterSpeed[i])
			maxSpeed = model.functions.speedLevel[0].rpmSetting_gerCalmWaterSpeed[i];
	}

	if (model.params.calmWaterSpeedCompare > 0) {
		if (minSpeed > model.params.calmWaterSpeedCompare) {
			errlog("ERROR! calmWaterSpeedCompared is %.3lf but minSpeed given in shipSpeedSettings is %.3lf, I use the later one\n",
				model.params.calmWaterSpeedCompare / model.params.knots_to_km, minSpeed / model.params.knots_to_km);
			model.params.calmWaterSpeedCompare = minSpeed;
		}
		if (maxSpeed < model.params.calmWaterSpeedCompare) {
			errlog("ERROR! calmWaterSpeedCompared is %.3lf but maxSpeed given in shipSpeedSettings is %.3lf, I use the later one\n",
				model.params.calmWaterSpeedCompare / model.params.knots_to_km, maxSpeed / model.params.knots_to_km);
			model.params.calmWaterSpeedCompare = maxSpeed;
		}
		model.params.preferredSpeed_calmWater = model.params.calmWaterSpeedCompare;
		errlog("OBS! Setting preferred speed to calmWaterSpeedCompared: %.2lf knots (it is modified if eta is given)\n",
			model.params.preferredSpeed_calmWater / model.params.knots_to_km);
	}
	else {
		model.params.preferredSpeed_calmWater = averSpeed / model.functions.speedLevel[0].nShip_speedSettings;
		errlog("OBS! Setting preferred speed to average of all speed settings right now: %.2lf knots (it is modified if eta is given)\n",
			model.params.preferredSpeed_calmWater / model.params.knots_to_km);
	}
	model.params.calmWaterSpeedMin = minSpeed;
	model.params.calmWaterSpeedMax = maxSpeed;
	//errlog("ERROR! ERROR! Modify so the rpeferredSpeed_calmWater uses the objective when calculated, ie min time -> high speed, min emission -> most economical speed aso\n");


}

int readParameterInfoForTable(json data, strTableParam* param, std::string namn, int useFactor, double skalning = 1.0) {
	int nError = 0;
	if (useFactor == 0)
		skalning = 1.0;

	if (!data[namn].is_null()) {
		json dataNu = data[namn];
		if (!dataNu["minValue"].is_null()) {
			param->minValue = (double)(dataNu["minValue"]) * skalning;
		}
		else {
			errlog("ERROR! minValue is missing for parameter %s\n", namn.c_str());
			nError = 1;
		}
		if (!dataNu["maxValue"].is_null()) {
			param->maxValue = (double)(dataNu["maxValue"]) * skalning;
		}
		else {
			errlog("ERROR! maxValue is missing for parameter %s\n", namn.c_str());
			nError = 1;
		}
		if (!dataNu["intervalSize"].is_null()) {
			param->intervalSize = (double)(dataNu["intervalSize"]) * skalning;
		}
		else {
			errlog("ERROR! minValue is missing for parameter %s\n", namn.c_str());
			nError = 1;
		}
	}
	else {
		errlog("ERROR! parameter %s is missing for table\n", namn.c_str());
		nError = 1;
	}
	return nError;
}

int readAddParameterInfoForTable(json data, strTableParam* param, std::string namn) {
	int nError = 0;

	if (!data[namn].is_null()) {
		json dataNu = data[namn];
		if (!dataNu["minValue"].is_null()) {
			param->minValue = dataNu["minValue"];
		}
		else {
			errlog("ERROR! minValue is missing for parameter %s\n", namn.c_str());
			nError = 1;
		}
		if (!dataNu["maxValue"].is_null()) {
			param->maxValue = dataNu["maxValue"];
		}
		else {
			errlog("ERROR! maxValue is missing for parameter %s\n", namn.c_str());
			nError = 1;
		}
		if (!dataNu["intervalSize"].is_null()) {
			param->intervalSize = dataNu["intervalSize"];
		}
		else {
			errlog("ERROR! minValue is missing for parameter %s\n", namn.c_str());
			nError = 1;
		}
	}
	else {
		errlog("ERROR! parameter %s is missing for table\n", namn.c_str());
		nError = 1;
	}

	if (nError == 0) {
		param->inv_intervalSize = 1 / param->intervalSize;
		param->nIndex = (int)((param->maxValue - param->minValue) * param->inv_intervalSize) + 1;
		//printf("nIndex %d float %.3lf\n", param->nIndex, ((param->maxValue - param->minValue) * param->inv_intervalSize) + 1);
		if(param->nIndex < ((param->maxValue - param->minValue) * param->inv_intervalSize) + 0.001)
			(param->nIndex)++;
	}

	return nError;
}

int loadTablesInfo(int useFactor)
{

	std::ifstream fil;
	char* namn;
	std::string nameTable;
	namn = (char*)malloc2(256 * sizeof(char));
	sprintf(namn, "%s/table_parameters.json", model.params.indataPath.c_str());
	errlog("trying to open %s\n", namn);
	if (!(check_file_exist(namn))) {
		errlog("%s does not exist. I quit\n", namn);
		printf("%s does not exist. I quit\n", namn);
		postRequest(std::string(namn) + " does not exist. I quit", 1);
	}
	printf("opens %s\n", namn);
	fil.open(namn);

	json data;

	try {
		fil >> data;
	}
	catch (...) {
		errlog("ERROR! json file %s is not valid. Fix it and run OptiNav again.\n", namn);
		printf("ERROR! json file %s is not valid. Fix it and run OptiNav again.\n", namn);
		postRequest("ERROR! json file " + std::string(namn) + " is not valid.Fix it and run OptiNav again.", 1);
	}

	int typeNr, pos, paramsError, i;

	model.tables.nBasAlloc = 20;
	for (i = 0; i < 3; i++) {
		model.tables.nTableTyp[i] = 0;
		model.tables.nAllocTableTyp[i] = model.tables.nBasAlloc;
		model.tables.tableTyp[i] = (strTableTyp*)malloc2(model.tables.nAllocTableTyp[i] * sizeof(strTableTyp));
	}

	std::string namnID, tableID;

	for (auto it = data.begin(); it != data.end(); ++it) {
		json dataTable = it.value();

		if (!dataTable["tableType"].is_null()) {
			if (!dataTable["tableID"].is_null())
				tableID = str_alloc_cpyString(cleanString(dataTable["tableID"]));
			else {
				errlog("ERROR! tableID missing for a table in %s. It must be there, I skip this one.\n", namn);
				continue;
			}

			std::string tableType = dataTable["tableType"];
			if (tableType == "wind")
				typeNr = 0;
			else if (tableType == "wave")
				typeNr = 1;
			else if (tableType == "stability")
				typeNr = 2;

			if (useFactor == 1) {
				if (typeNr == 0)
					namnID = model.functions.windTableID;
				else if (typeNr == 1)
					namnID = model.functions.waveTableID;
				else if (typeNr == 2)
					namnID = model.functions.stabilityTableID;
				if (namnID != tableID)
					continue;
			}

			pos = model.tables.nTableTyp[typeNr];
			if (pos >= model.tables.nAllocTableTyp[typeNr]) {
				model.tables.nAllocTableTyp[typeNr] += model.tables.nBasAlloc;
				model.tables.tableTyp[typeNr] = (strTableTyp*)realloc(model.tables.tableTyp[typeNr], model.tables.nAllocTableTyp[typeNr] * sizeof(strTableTyp));
			}

			model.tables.tableTyp[typeNr][pos].tableID = str_alloc_cpyString(cleanString(dataTable["tableID"]));

			if (!dataTable["tableID"].is_null())
				model.tables.tableTyp[typeNr][pos].tableID = str_alloc_cpyString(cleanString(dataTable["tableID"]));
			else {
				errlog("ERROR! tableID missing for a table in %s. It must be there, I skip this one.\n", namn);
				continue;
			}

			if (!dataTable["fileName"].is_null())
				model.tables.tableTyp[typeNr][pos].fileName = str_alloc_cpyString(dataTable["fileName"]);
			else {
				errlog("ERROR! fileName is missing for tableID %s in %s. It must be there, I skip this one.\n", model.tables.tableTyp[typeNr][pos].tableID, namn);
				continue;
			}
			if (!dataTable["parameters"].is_null()) {
				paramsError = 0;
				json dataParam = dataTable["parameters"];
				if (typeNr == 0) { // wind
					paramsError += readParameterInfoForTable(dataTable["parameters"], &(model.tables.tableTyp[typeNr][pos].shipSpeedCalmWater), "shipSpeed_calmWater_knots", useFactor, model.params.knots_to_km);
					paramsError += readParameterInfoForTable(dataTable["parameters"], &(model.tables.tableTyp[typeNr][pos].windSpeed), "relativeWindSpeed_m_s", useFactor, 3.6);
					paramsError += readParameterInfoForTable(dataTable["parameters"], &(model.tables.tableTyp[typeNr][pos].windDirection), "relativeWindDirection", useFactor, M_PI / 180.0);
				}else if(typeNr == 1) { // wave
					paramsError += readParameterInfoForTable(dataTable["parameters"], &(model.tables.tableTyp[typeNr][pos].shipSpeedCalmWater), "shipSpeed_calmWater_knots", useFactor, model.params.knots_to_km);
					paramsError += readParameterInfoForTable(dataTable["parameters"], &(model.tables.tableTyp[typeNr][pos].waveHeight), "significantWaveHeight_m", useFactor);
					paramsError += readParameterInfoForTable(dataTable["parameters"], &(model.tables.tableTyp[typeNr][pos].wavePeriod), "meanWavePeriod_s", useFactor);
					paramsError += readParameterInfoForTable(dataTable["parameters"], &(model.tables.tableTyp[typeNr][pos].waveDirection), "relativeWaveDirection", useFactor, M_PI / 180.0);
					if (!dataTable["maxWaveHeight"].is_null()) {
						model.tables.tableTyp[typeNr][pos].maxWaveHeight = (double)(dataTable["maxWaveHeight"]);
					}
					else {
						errlog("ERROR! maxWaveHeight is missing for parameter %s, I set it to 8.5 meters\n", model.tables.tableTyp[typeNr][pos].fileName);
						model.tables.tableTyp[typeNr][pos].maxWaveHeight = 8.5;
					}
					if (!dataTable["maxWaveHeight_warning"].is_null()) {
						model.tables.tableTyp[typeNr][pos].maxWaveHeight_warning = (double)(dataTable["maxWaveHeight_warning"]);
					}
					else {
						errlog("OBS! No maxWaveHeight_warning is set for parameter %s, I set it to 7.0 meters\n", model.tables.tableTyp[typeNr][pos].fileName);
						model.tables.tableTyp[typeNr][pos].maxWaveHeight_warning = 7.0;
					}
				}
				else { // stability
					paramsError += readParameterInfoForTable(dataTable["parameters"], &(model.tables.tableTyp[typeNr][pos].windSpeed), "relativeWindSpeed_m_s", useFactor, 3.6);
					paramsError += readParameterInfoForTable(dataTable["parameters"], &(model.tables.tableTyp[typeNr][pos].windDirection), "relativeWindDirection", useFactor, M_PI / 180.0);
					paramsError += readParameterInfoForTable(dataTable["parameters"], &(model.tables.tableTyp[typeNr][pos].shipSpeedOverGround), "shipSpeedOverGround_knots", useFactor, model.params.knots_to_km);
				}
			}
			else {
				errlog("ERROR! parameters is missing for tableID %s in %s. It must be there, I skip this one.\n", model.tables.tableTyp[typeNr][pos].tableID, namn);
				continue;
			}
			if (paramsError > 0) {
				errlog("ERROR! tableID %s in file %s not read properly, error in parameters\n", model.tables.tableTyp[typeNr][pos].tableID, namn);
				continue;
			}

			(model.tables.nTableTyp[typeNr])++;
		}


	}

	for (i = 0; i < 3; i++) {
		if (model.tables.nTableTyp[i] < 1) {
			if (useFactor == 0) {
				errlog("ERROR! No tables in %s of type %d (0 wind, 1 wave, 2 stability). There must be at least one. I quit\n", namn, i);
				postRequest("ERROR! No tables in " + std::string(namn) + " of type " + std::to_string(i) + " (0 wind, 1 wave, 2 stability).There must be at least one.I quit", 1);
			}
			else {
				if (i == 0)
					namnID = model.functions.windTableID;
				else if (i == 1)
					namnID = model.functions.waveTableID;
				else if (i == 2)
					namnID = model.functions.stabilityTableID;
				errlog("ERROR! Table %s typ %d is not defined in table_parameters.json. Fix this, generate new redis values and then try again. I quit\n", namnID.c_str(), i);
				postRequest("ERROR! Table " + namnID + " is not defined in table_parameters.json. Fix this, generate new redis values and then try again. I quit", 1);
			}
		}
		for (int i1 = 0; i1 < model.tables.nTableTyp[i]; i1++) {
			for (int i2 = i1 + 1; i2 < model.tables.nTableTyp[i]; i2++) {
				if (strcmp(model.tables.tableTyp[i][i1].tableID, model.tables.tableTyp[i][i2].tableID) == 0) {
					errlog("ERROR! Two tables in %s with the same tableID (%S) type %d (0 wind, 1 wave, 2 stability). The first one will be used.\n",
						namn, model.tables.tableTyp[i][i2].tableID, i);
					break;
				}
			}
		}
	}

	if (useFactor == 1) {
		model.functions.windTableNr = 0;
		model.functions.waveTableNr = 0;
		model.functions.stabilityTableNr = 0;
	}


	fil.close();




	return 0;
}

